code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A colored stripe attached to the end of a 5-bar is extended across the bar.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            start = c
            while c + 1 < w and g[r][c + 1] == 5:
                c += 1
            end = c
            if end > start:
                for anchor in (start, end):
                    for dr in (-1, 1):
                        rr = r + dr
                        while 0 <= rr < h and g[rr][anchor] not in (0, 5):
                            color = g[rr][anchor]
                            for cc in range(start, end + 1):
                                if g[rr][cc] == 0:
                                    g[rr][cc] = color
                            rr += dr
            c += 1
    # A colored row-pattern beside a vertical 5-bar is repeated along its length.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            start = r
            while r + 1 < h and g[r + 1][c] == 5:
                r += 1
            end = r
            if end > start:
                for side in (-1, 1):
                    sc = c + side
                    if not 0 <= sc < w:
                        continue
                    # Seed must touch the vertical bar; use the contiguous colored
                    # run on the adjacent column and its contiguous horizontal row pattern.
                    seed_rows = [rr for rr in range(start, end + 1) if g[rr][sc] not in (0, 5)]
                    if not seed_rows:
                        continue
                    lo, hi = min(seed_rows), max(seed_rows)
                    if any(g[rr][sc] in (0, 5) for rr in range(lo, hi + 1)):
                        continue
                    profiles = []
                    for rr in range(lo, hi + 1):
                        row = []
                        cc = sc
                        step = 1 if side == 1 else -1
                        while 0 <= cc < w and g[rr][cc] not in (0, 5):
                            row.append(g[rr][cc])
                            cc += step
                        profiles.append(row)
                    for rr in range(start, end + 1):
                        prof = profiles[(rr - lo) % len(profiles)]
                        cc = sc
                        step = 1 if side == 1 else -1
                        for color in prof:
                            if g[rr][cc] == 0:
                                g[rr][cc] = color
                            cc += step
    return g
'''
